//! Local-only LeetCode parity on a real vault (never in the gate, never committed data: the repo is public).
//! `MDA_LEETCODE_VAULT=<vault> cargo test -p mda-core --test leetcode_vault_local -- --ignored`; expectations
//! default to the gitignored `docs/conformance-gen/leetcode/vault-expected/` (override with
//! `MDA_LEETCODE_VAULT_EXPECTED`), regenerated by `docs/conformance-gen/leetcode/export.cjs` from the extension.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)] // test file

use std::path::{Path, PathBuf};

fn md_files(dir: &Path, out: &mut Vec<PathBuf>) {
    for e in std::fs::read_dir(dir).unwrap().flatten() {
        let p = e.path();
        let hidden = e.file_name().to_string_lossy().starts_with('.');
        if p.is_dir() && !hidden {
            md_files(&p, out);
        } else if p.extension().is_some_and(|x| x == "md") {
            out.push(p);
        }
    }
}

#[test]
#[ignore = "local only: needs MDA_LEETCODE_VAULT"]
fn real_vault_matches_the_extension() {
    let vault = PathBuf::from(std::env::var("MDA_LEETCODE_VAULT").expect("MDA_LEETCODE_VAULT"));
    let expected = std::env::var("MDA_LEETCODE_VAULT_EXPECTED").map_or_else(
        |_| {
            Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("../../docs/conformance-gen/leetcode/vault-expected")
        },
        PathBuf::from,
    );
    let mut files = Vec::new();
    md_files(&vault, &mut files);
    files.sort();
    let mut bad = Vec::new();
    for f in &files {
        let rel = f.strip_prefix(&vault).unwrap();
        let src = mda_core::parse::decode(&std::fs::read(f).unwrap());
        let got = serde_json::to_string(&mda_core::leetcode::parse(&src)).unwrap();
        let want_path = expected.join(rel).with_extension("expected.json");
        let want: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(&want_path).unwrap()).unwrap();
        if got != serde_json::to_string(&want).unwrap() {
            bad.push(rel.display().to_string());
        }
    }
    assert!(!files.is_empty(), "no .md under {}", vault.display());
    assert!(
        bad.is_empty(),
        "{} of {} differ:\n{}",
        bad.len(),
        files.len(),
        bad.join("\n")
    );
}
